def _sha256_bytes(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def _sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for chunk in iter(lambda: stream.read(1 << 20), b""):
            digest.update(chunk)
    return digest.hexdigest()


def _canonical_json(payload: object) -> bytes:
    return (json.dumps(payload, ensure_ascii=False, sort_keys=True, separators=(",", ":")) + "\n").encode()


def _atomic_write(path: Path, data: bytes) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    fd, temp_name = tempfile.mkstemp(prefix=f".{path.name}.", suffix=".tmp", dir=path.parent)
    temp = Path(temp_name)
    try:
        with os.fdopen(fd, "wb") as stream:
            stream.write(data)
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(temp, path)
        try:
            dir_fd = os.open(path.parent, os.O_RDONLY | getattr(os, "O_DIRECTORY", 0))
        except OSError:
            return
        try:
            os.fsync(dir_fd)
        finally:
            os.close(dir_fd)
    finally:
        temp.unlink(missing_ok=True)


def _iter_top_level_array(path: Path, key: str) -> Iterator[JsonObject]:
    """Incrementally decode one top-level JSON array with the stdlib only."""

    marker = json.dumps(key)
    decoder = json.JSONDecoder()
    with path.open("r", encoding="utf-8") as stream:
        prefix = ""
        while marker not in prefix:
            chunk = stream.read(1 << 16)
            if not chunk:
                raise RuntimeError(f"top-level JSON key {key!r} is missing from {path}")
            prefix += chunk
        marker_end = prefix.index(marker) + len(marker)
        buffer = prefix[marker_end:]
        cursor = 0
        eof = False

        def refill() -> bool:
            nonlocal buffer, eof
            if eof:
                return False
            chunk = stream.read(1 << 16)
            if not chunk:
                eof = True
                return False
            buffer += chunk
            return True

        def skip_space() -> bool:
            nonlocal cursor
            while True:
                while cursor < len(buffer) and buffer[cursor].isspace():
                    cursor += 1
                if cursor < len(buffer):
                    return True
                if not refill():
                    return False

        if not skip_space() or buffer[cursor] != ":":
            raise RuntimeError(f"malformed JSON key/value separator for {key}")
        cursor += 1
        if not skip_space() or buffer[cursor] != "[":
            raise RuntimeError(f"top-level JSON value {key!r} is not an array")
        cursor += 1
        first = True

        while True:
            if not skip_space():
                raise RuntimeError(f"unterminated JSON array {key!r}")
            if buffer[cursor] == "]":
                if first:
                    return
                cursor += 1
                return
            if not first:
                if buffer[cursor] != ",":
                    raise RuntimeError(f"missing comma in JSON array {key!r}")
                cursor += 1
                if not skip_space() or buffer[cursor] == "]":
                    raise RuntimeError(f"invalid trailing comma in JSON array {key!r}")

            while True:
                try:
                    value, end = decoder.raw_decode(buffer, cursor)
                except json.JSONDecodeError:
                    if not refill():
                        raise RuntimeError(f"invalid or truncated JSON object in {key!r}")
                    continue
                if not isinstance(value, dict):
                    raise RuntimeError(f"non-object row in JSON array {key!r}")
                yield value
                cursor = end
                first = False
                if cursor >= 1 << 16:
                    buffer = buffer[cursor:]
                    cursor = 0
                break


def _engine_identity(repo_root: Path) -> JsonObject:
    if not Path(ttc.__file__).resolve().is_relative_to(ENGINE_SRC.resolve()):
        raise RuntimeError(f"cycle engine imported outside this run's engine tree: {ttc.__file__}")
    if not Path(scorer.__file__).resolve().is_relative_to(ENGINE_SRC.resolve()):
        raise RuntimeError(f"canonical scorer imported outside this run's engine tree: {scorer.__file__}")
    if not Path(sealed.__file__).resolve().is_relative_to(ENGINE_SRC.resolve()):
        raise RuntimeError(f"sealed portfolio module imported outside this run's engine tree: {sealed.__file__}")
    modules: dict[str, JsonObject] = {}
    for relative, (expected_blob, expected_sha256) in ENGINE_BLOBS.items():
        path = ENGINE_SRC / relative
        raw = path.read_bytes()
        blob = subprocess.run(
            ["git", "-C", str(repo_root), "hash-object", str(path)],
            check=True,
            capture_output=True,
            text=True,
        ).stdout.strip()
        sha = _sha256_bytes(raw)
        if blob != expected_blob or sha != expected_sha256:
            raise RuntimeError(f"engine identity mismatch for {relative}: blob={blob} sha256={sha}")
        modules[relative] = {"GIT_BLOB": blob, "SHA256": sha}
    return {
        "ENGINE_COMMIT": ENGINE_COMMIT,
        "ENGINE_IDENTITY": "BYTE_IDENTICAL_TO_7d3ea86",
        "MODULES": modules,
    }


def _load_recorded_ties(repo_root: Path) -> tuple[JsonObject, bytes, Portfolio, dict[str, JsonObject]]:
    source_bytes = subprocess.run(
        ["git", "-C", str(repo_root), "show", f"{SOURCE_COMMIT}:{SOURCE_PATH}"],
        check=True,
        capture_output=True,
    ).stdout
    if _sha256_bytes(source_bytes) != SOURCE_SHA256:
        raise RuntimeError("pinned root-family source artifact SHA256 drift")
    source = json.loads(source_bytes)
    if source["BEST_CANONICAL_RECOUNT_STATUS"] != "PASS" or source["BEST_COUNT"] != ROOT_COUNT:
        raise RuntimeError("pinned source result does not establish a canonical v7 tie set")
    root = ttc.normalize_portfolio(
        source["STARTING_PORTFOLIO"], pool_size=POOL, expected_ticket_count=20  # type: ignore[arg-type]
    )
    if ttc.portfolio_sha256(root, pool_size=POOL) != ROOT_SHA256:
        raise RuntimeError("canonical v7 root portfolio SHA256 drift")
    if source["STARTING_COUNT"] != ROOT_COUNT or source["STARTING_PORTFOLIO_SHA256"] != ROOT_SHA256:
        raise RuntimeError("pinned source result root identity drift")
    ties = source["BEST_CANONICAL_RECOUNT"]
    if not isinstance(ties, list) or len(ties) != EXPECTED_RECORDED_TIES:
        raise RuntimeError(f"expected {EXPECTED_RECORDED_TIES} recorded equal-count candidates")
    expected: dict[str, JsonObject] = {}
    for row in ties:
        sha = str(row["SHA256"])
        if row["CANONICAL_COUNT"] != ROOT_COUNT or row["RESIDUAL_COUNT"] != ROOT_COUNT or row["MATCH"] is not True:
            raise RuntimeError(f"source tie {sha} is not a recorded canonical equal-count candidate")
        if sha in expected:
            raise RuntimeError(f"duplicate SHA in pinned source ties: {sha}")
        expected[sha] = row
    return source, source_bytes, root, expected


def _load_only_recorded_portfolios(
    repo_root: Path, expected: dict[str, JsonObject]
) -> tuple[dict[str, Portfolio], int, str]:
    archive = repo_root / ARCHIVE_PATH
    archive_sha = _sha256_file(archive)
    if archive_sha != ARCHIVE_SHA256:
        raise RuntimeError(f"neutral portfolio archive SHA256 drift: {archive_sha}")
    pilot = json.loads((repo_root / PILOT_RESULT_PATH).read_bytes())
    if (
        pilot["STATUS"] != "COMPLETE"
        or pilot["CANONICAL_START_COUNT"] != ROOT_COUNT
        or pilot["CANONICAL_START_SHA256"] != ROOT_SHA256
        or pilot["NEUTRAL_PORTFOLIOS_SHA256"] != archive_sha
    ):
        raise RuntimeError("neutral archive provenance does not match its completed pilot result")

    selected: dict[str, Portfolio] = {}
    rows_seen = 0
    for row in _iter_top_level_array(archive, "NEUTRAL_PORTFOLIOS"):
        rows_seen += 1
        sha = row.get("SHA256")
        if sha not in expected:
            continue
        sha = str(sha)
        if sha in selected:
            raise RuntimeError(f"recorded equal-count SHA occurs more than once in the archive: {sha}")
        portfolio = ttc.normalize_portfolio(
            row["PORTFOLIO"], pool_size=POOL, expected_ticket_count=20  # type: ignore[arg-type]
        )
        if ttc.portfolio_sha256(portfolio, pool_size=POOL) != sha:
            raise RuntimeError(f"archive portfolio identity mismatch for {sha}")
        if row.get("RESIDUAL_COUNT") != ROOT_COUNT or expected[sha]["CANONICAL_COUNT"] != ROOT_COUNT:
            raise RuntimeError(f"archive/source count mismatch for {sha}")
        selected[sha] = portfolio
        if len(selected) % 20 == 0 or len(selected) == len(expected):
            print(
                json.dumps(
                    {"ARCHIVE_ROWS_SCANNED": rows_seen, "RECORDED_PORTFOLIOS_FOUND": len(selected)},
                    sort_keys=True,
                ),
                flush=True,
            )
    if rows_seen != EXPECTED_ARCHIVE_ROWS:
        raise RuntimeError(f"archive row count drift: expected {EXPECTED_ARCHIVE_ROWS}, found {rows_seen}")
    if set(selected) != set(expected):
        missing = sorted(set(expected) - set(selected))
        raise RuntimeError(f"recorded equal-count portfolios missing from archive: {missing[:5]}")
    return selected, rows_seen, archive_sha


def _structural_distance(left: TicketSet, right: TicketSet) -> int:
    return len(left.symmetric_difference(right))


def _select_next(
    candidates: dict[str, Portfolio],
    ticket_sets: dict[str, TicketSet],
    selected: list[str],
    pair_distance,
) -> tuple[str, int, int, int, int]:
    """Apply exact maximin lexicographic distance, scoring signatures only at primary ties."""

    nearest_structural: dict[str, int] = {}
    structural_neighbors: dict[str, list[str]] = {}
    for sha in candidates:
        if sha in selected:
            continue
        distances = [(_structural_distance(ticket_sets[sha], ticket_sets[prior]), prior) for prior in selected]
        minimum = min(distance for distance, _prior in distances)
        nearest_structural[sha] = minimum
        structural_neighbors[sha] = [prior for distance, prior in distances if distance == minimum]

    maximum_structural = max(nearest_structural.values())
    structural_ties = [sha for sha, distance in nearest_structural.items() if distance == maximum_structural]
    nearest_residual = {
        sha: min(pair_distance(sha, prior)[1] for prior in structural_neighbors[sha])
        for sha in structural_ties
    }
    pick = min(structural_ties, key=lambda sha: (-nearest_residual[sha], sha))
    residual_comparisons = sum(len(structural_neighbors[sha]) for sha in structural_ties)
    return (
        pick,
        nearest_structural[pick],
        nearest_residual[pick],
        len(structural_ties),
        residual_comparisons,
    )


def _payload_digest(entries: list[JsonObject]) -> str:
    return _sha256_bytes(_canonical_json(entries))


def _cache_payload(
    source_sha: str, archive_sha: str, entries: dict[tuple[str, str], tuple[int, int]]
) -> bytes:
    rows = [
        {
            "SHA_A": pair[0],
            "SHA_B": pair[1],
            "STRUCTURAL_DISTANCE": value[0],
            "RESIDUAL_SIGNATURE_DISTANCE": value[1],
        }
        for pair, value in sorted(entries.items())
    ]
    return _canonical_json(
        {
            "TASK_ID": TASK_ID,
            "SOURCE_RESULT_SHA256": source_sha,
            "PORTFOLIO_ARCHIVE_SHA256": archive_sha,
            "DISTANCE_FORMULA": "(2*C(A union B)-C(A)-C(B))/7; exact 7-subset signature Hamming distance",
            "ENTRIES": rows,
            "ENTRIES_SHA256": _payload_digest(rows),
        }
    )


def _load_cache(
    path: Path,
    source_sha: str,
    archive_sha: str,
    portfolios: dict[str, Portfolio],
    ticket_sets: dict[str, TicketSet],
) -> dict[tuple[str, str], tuple[int, int]]:
    if not path.exists():
        return {}
    data = json.loads(path.read_bytes())
    if (
        data.get("TASK_ID") != TASK_ID
        or data.get("SOURCE_RESULT_SHA256") != source_sha
        or data.get("PORTFOLIO_ARCHIVE_SHA256") != archive_sha
        or data.get("DISTANCE_FORMULA")
        != "(2*C(A union B)-C(A)-C(B))/7; exact 7-subset signature Hamming distance"
    ):
        raise RuntimeError("selection distance cache identity mismatch")
    rows = data.get("ENTRIES")
    if not isinstance(rows, list) or data.get("ENTRIES_SHA256") != _payload_digest(rows):
        raise RuntimeError("selection distance cache digest mismatch")
    result: dict[tuple[str, str], tuple[int, int]] = {}
    for row in rows:
        a, b = str(row["SHA_A"]), str(row["SHA_B"])
        pair = tuple(sorted((a, b)))
        if a == b or a not in ticket_sets or b not in ticket_sets or pair in result:
            raise RuntimeError("invalid or duplicate selection cache pair")
        structural = int(row["STRUCTURAL_DISTANCE"])
        residual = int(row["RESIDUAL_SIGNATURE_DISTANCE"])
        if structural != _structural_distance(ticket_sets[a], ticket_sets[b]) or residual < 0:
            raise RuntimeError(f"invalid cached distance for {pair}")
        result[pair] = (structural, residual)
    return result


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--repo-root", type=Path, required=True)
    parser.add_argument("--run-root", type=Path, required=True)
    args = parser.parse_args()
    repo_root = args.repo_root.resolve()
    run_root = args.run_root.resolve()
    if run_root != RUN_ROOT:
        raise RuntimeError(f"script/run-root mismatch: {run_root} != {RUN_ROOT}")
    if ttc.K20_RAW_ATTEMPT_CAP != 492480:
        raise RuntimeError("pinned cycle engine family-size constant drift")
    engine_identity = _engine_identity(repo_root)
    _source, _source_bytes, root, expected = _load_recorded_ties(repo_root)
    candidates, archive_rows, archive_sha = _load_only_recorded_portfolios(repo_root, expected)
    root_set: TicketSet = frozenset(root)
    portfolios: dict[str, Portfolio] = {ROOT_SHA256: root, **candidates}
    ticket_sets: dict[str, TicketSet] = {sha: frozenset(p) for sha, p in portfolios.items()}
    root_among_recorded_ties = ROOT_SHA256 in candidates
    neutral_archive_portfolios_loaded = len(candidates)
    candidates.pop(ROOT_SHA256, None)
    if len(candidates) < EXPECTED_STARTS:
        raise RuntimeError("fewer recorded neutral candidates than requested starts")
    if ROOT_SHA256 in candidates:
        raise RuntimeError("root exclusion failed")
    root_distances = {sha: _structural_distance(root_set, ticket_sets[sha]) for sha in candidates}
    if any(distance == 0 for distance in root_distances.values()):
        raise RuntimeError("non-root neutral candidate has zero structural distance")

    cache_path = run_root / "pair-distance-cache.json"
    cache = _load_cache(cache_path, SOURCE_SHA256, archive_sha, portfolios, ticket_sets)
    calls = 0
    cache_flush_at = len(cache) + 20
    begun = time.perf_counter()

    def pair_distance(a: str, b: str) -> tuple[int, int]:
        nonlocal calls, cache_flush_at
        pair = tuple(sorted((a, b)))
        if pair in cache:
            return cache[pair]
        structural = _structural_distance(ticket_sets[a], ticket_sets[b])
        union = tuple(sorted(set(portfolios[a]).union(portfolios[b])))
        normalized_union = ttc.normalize_portfolio(union, pool_size=POOL)
        union_count = ttc.official_any_prize_outcome_count(
            normalized_union, pool_size=POOL, draws=draws
        )
        numerator = 2 * union_count - ROOT_COUNT - ROOT_COUNT
        if numerator < 0 or numerator % 7:
            raise RuntimeError(
                f"residual-signature formula invalid for {pair}: numerator={numerator}"
            )
        result = (structural, numerator // 7)
        cache[pair] = result
        calls += 1
        if len(cache) >= cache_flush_at:
            _atomic_write(cache_path, _cache_payload(SOURCE_SHA256, archive_sha, cache))
            cache_flush_at = len(cache) + 20
        if calls % 20 == 0:
            print(
                json.dumps(
                    {
                        "DISTANCE_SCORER_CALLS_THIS_RUN": calls,
                        "DISTANCE_CACHE_PAIRS": len(cache),
                        "ELAPSED_SECONDS": round(time.perf_counter() - begun, 1),
                    },
                    sort_keys=True,
                ),
                flush=True,
            )
        return result

    draws = ttc.load_draws(POOL)
    print(
        json.dumps(
            {
                "SOURCE_CANDIDATES": len(expected),
                "RECORDED_PORTFOLIOS_LOADED": neutral_archive_portfolios_loaded,
                "ROOT_EXCLUDED": True,
                "ARCHIVE_ROWS_SCANNED": archive_rows,
                "CACHE_PAIRS_RESUMED": len(cache),
                "ENGINE_COMMIT": ENGINE_COMMIT,
            },
            sort_keys=True,
        ),
        flush=True,
    )

    root_residual: dict[str, int] = {}
    for index, sha in enumerate(sorted(candidates), start=1):
        root_residual[sha] = pair_distance(ROOT_SHA256, sha)[1]
        if index % 20 == 0 or index == len(candidates):
            print(
                json.dumps({"ROOT_DISTANCES_DONE": index, "ROOT_DISTANCE_TOTAL": len(candidates)}),
                flush=True,
            )

    first = min(
        candidates,
        key=lambda sha: (-root_distances[sha], -root_residual[sha], sha),
    )
    selected = [first]
    selection_log: list[JsonObject] = [
        {
            "PICK": 1,
            "SHA256": first,
            "MIN_STRUCTURAL_DISTANCE_TO_PRIOR": root_distances[first],
            "MIN_RESIDUAL_SIGNATURE_DISTANCE_TO_PRIOR": root_residual[first],
            "CRITERION": "maximum ROOT pair (structural distance, residual-signature distance); SHA ascending final tie-break",
        }
    ]
    while len(selected) < EXPECTED_STARTS:
        pick, structural, residual, tie_count, residual_comparisons = _select_next(
            candidates, ticket_sets, selected, pair_distance
        )
        selected.append(pick)
        selection_log.append(
            {
                "PICK": len(selected),
                "SHA256": pick,
                "MIN_STRUCTURAL_DISTANCE_TO_PRIOR": structural,
                "MIN_RESIDUAL_SIGNATURE_DISTANCE_TO_PRIOR": residual,
                "CRITERION": "maximize the minimum lexicographic pair (structural distance, residual-signature distance) to prior selected starts; SHA ascending final tie-break",
                "PRIMARY_STRUCTURAL_TIE_COUNT": tie_count,
                "RESIDUAL_COMPARISONS": residual_comparisons,
            }
        )

    selected_structural = [root_distances[sha] for sha in selected]
    selected_pair_structural: list[int] = []
    selected_pair_residual: list[int] = []
    for i, a in enumerate(selected):
        for b in selected[i + 1 :]:
            d_struct, d_residual = pair_distance(a, b)
            selected_pair_structural.append(d_struct)
            selected_pair_residual.append(d_residual)

    _atomic_write(cache_path, _cache_payload(SOURCE_SHA256, archive_sha, cache))

    starts: list[JsonObject] = []
    for index, sha in enumerate(selected, start=1):
        recorded = expected[sha]
        starts.append(
            {
                "START_INDEX": index,
                "SHA256": sha,
                "COUNT": ROOT_COUNT,
                "ROOT_DISTANCE": root_distances[sha],
                "ROOT_RESIDUAL_SIGNATURE_DISTANCE": root_residual[sha],
                "MIN_STRUCTURAL_DISTANCE_TO_PRIOR_SELECTED": selection_log[index - 1][
                    "MIN_STRUCTURAL_DISTANCE_TO_PRIOR"
                ],
                "MIN_RESIDUAL_SIGNATURE_DISTANCE_TO_PRIOR_SELECTED": selection_log[index - 1][
                    "MIN_RESIDUAL_SIGNATURE_DISTANCE_TO_PRIOR"
                ],
                "RECORDED_CANONICAL_RECOUNT": recorded["CANONICAL_COUNT"],
                "RECORDED_RESIDUAL_COUNT": recorded["RESIDUAL_COUNT"],
                "CYCLE_INDICES": recorded["INDICES"],
                "CYCLE_NUMBERS": recorded["NUMBERS"],
                "CYCLE_DIRECTION": recorded["DIRECTION"],
                "PORTFOLIO": [list(ticket) for ticket in candidates[sha]],
            }
        )

    payload: JsonObject = {
        "TASK_ID": TASK_ID,
        "ROOT_COUNT": ROOT_COUNT,
        "ROOT_SHA256": ROOT_SHA256,
        "ROOT_PORTFOLIO": [list(ticket) for ticket in root],
        "SOURCE_RESULT_COMMIT": SOURCE_COMMIT,
        "SOURCE_RESULT_PATH": SOURCE_PATH,
        "SOURCE_RESULT_SHA256": SOURCE_SHA256,
        "SOURCE_TIES_AVAILABLE": len(expected),
        "ROOT_AMONG_RECORDED_TIES": root_among_recorded_ties,
        "SOURCE_TIES_ALL_CANONICALLY_RECOUNTED": True,
        "PORTFOLIO_ARCHIVE_PATH": ARCHIVE_PATH,
        "PORTFOLIO_ARCHIVE_SHA256": archive_sha,
        "ARCHIVE_ROWS_SCANNED": archive_rows,
        "NEUTRAL_CANDIDATES_AVAILABLE": len(candidates),
        "NEUTRAL_STARTS_SELECTED": len(starts),
        "DISTANCE_METRIC": "ticket-set symmetric difference cardinality",
        "RESIDUAL_SIGNATURE_METRIC": "Hamming distance on uncovered 7-number subsets after R+S",
        "RESIDUAL_SIGNATURE_DISTANCE_FORMULA": "(2*C(A union B)-C(A)-C(B))/7; C is exact canonical OFFICIAL_ANY_PRIZE outcome count",
        "SELECTION_RULE": [
            "Load only archive portfolios whose canonical SHA occurs in the 362 source-result equal-count rows; require recorded canonical and residual counts equal ROOT_COUNT; exclude ROOT_SHA256.",
            "Pick 1 by maximum ticket-set symmetric difference from ROOT; within structural ties maximize exact residual-signature distance from ROOT; final tie-break lowest canonical SHA256.",
            "For each later pick, calculate for every remaining candidate the minimum lexicographic pair (ticket-set structural distance, exact residual-signature distance) to the already selected starts; maximize that pair; final tie-break lowest canonical SHA256.",
            "Residual-signature distances use canonical exact scorer counts for the deduplicated ticket union; no sampled or approximate distance values.",
        ],
        "SELECTION_LOG": selection_log,
        "STRUCTURAL_DISTANCE_TO_ROOT": {
            "MIN": min(selected_structural),
            "MAX": max(selected_structural),
            "MEAN": sum(selected_structural) / len(selected_structural),
        },
        "SELECTED_PAIRWISE_STRUCTURAL_DISTANCE": {
            "MIN": min(selected_pair_structural),
            "MAX": max(selected_pair_structural),
            "MEAN": sum(selected_pair_structural) / len(selected_pair_structural),
        },
        "SELECTED_PAIRWISE_RESIDUAL_SIGNATURE_DISTANCE": {
            "MIN": min(selected_pair_residual),
            "MAX": max(selected_pair_residual),
            "MEAN": sum(selected_pair_residual) / len(selected_pair_residual),
        },
        "DISTANCE_CACHE_PATH": str(cache_path.relative_to(repo_root)),
        "DISTANCE_CACHE_SHA256": _sha256_file(cache_path) if cache_path.exists() else None,
        "ENGINE_IDENTITY": engine_identity,
        "STARTS": starts,
    }
    payload_digest = _sha256_bytes(_canonical_json(payload))
    payload["SELECTION_PAYLOAD_SHA256"] = payload_digest
    output = run_root / "neutral-starts.json"
    sidecar = run_root / "neutral-starts.json.sha256"
    if output.exists() or sidecar.exists():
        raise RuntimeError("neutral-starts.json is already frozen; refusing to overwrite")
    output_bytes = json.dumps(payload, ensure_ascii=False, sort_keys=True, indent=1).encode() + b"\n"
    _atomic_write(output, output_bytes)
    file_sha = _sha256_bytes(output_bytes)
    _atomic_write(sidecar, f"{file_sha}  neutral-starts.json\n".encode())
    print(
        json.dumps(
            {
                "NEUTRAL_CANDIDATES_AVAILABLE": len(candidates),
                "NEUTRAL_STARTS_SELECTED": len(starts),
                "STRUCTURAL_DISTANCE_TO_ROOT": payload["STRUCTURAL_DISTANCE_TO_ROOT"],
                "SELECTED_PAIRWISE_STRUCTURAL_DISTANCE": payload["SELECTED_PAIRWISE_STRUCTURAL_DISTANCE"],
                "FULL_FROZEN_FILE_SHA256": file_sha,
                "SELECTION_PAYLOAD_SHA256": payload_digest,
                "DISTANCE_CACHE_PAIRS": len(cache),
                "DISTANCE_SCORER_CALLS_THIS_RUN": calls,
            },
            sort_keys=True,
        ),
        flush=True,
    )
    return 0


